<body>
    <div class="todo-container">
        <h1>📝 Todo App</h1>

        <div class="input-group">
            <input type="text" id="todoInput" placeholder="Add a new todo..." onkeypress="handleKeyPress(event)">
            <button class="add-btn" onclick="addTodo()">Add</button>
        </div>

        <div class="filters">
            <button class="filter-btn active" onclick="setFilter('all')">All</button>
            <button class="filter-btn" onclick="setFilter('active')">Active</button>
            <button class="filter-btn" onclick="setFilter('completed')">Completed</button>
        </div>

        <ul class="todo-list" id="todoList">
            <li class="empty-state">No todos yet. Add one above!</li>
        </ul>

        <div class="stats" id="stats">
            0 items left
        </div>
    </div>

    <script>
        // State
        let todos = [];
        let currentFilter = 'all';

        // Initialize
        document.addEventListener('DOMContentLoaded', loadTodos);

        // Load todos from localStorage
        function loadTodos() {
            const saved = localStorage.getItem('todos');
            if (saved) {
                todos = JSON.parse(saved);
            }
            renderTodos();
        }

        // Save todos to localStorage
        function saveTodos() {
            localStorage.setItem('todos', JSON.stringify(todos));
        }

        // Add new todo
        function addTodo() {
            const input = document.getElementById('todoInput');
            const text = input.value.trim();

            if (text === '') {
                input.focus();
                return;
            }

            const todo = {
                id: Date.now(),
                text: text,
                completed: false
            };

            todos.unshift(todo);
            saveTodos();
            renderTodos();
            input.value = '';
            input.focus();
        }

        // Handle Enter key
        function handleKeyPress(event) {
            if (event.key === 'Enter') {
                addTodo();
            }
        }

        // Toggle todo completion
        function toggleTodo(id) {
            todos = todos.map(todo => 
                todo.id === id ? { ...todo, completed: !todo.completed } : todo
            );
            saveTodos();
            renderTodos();
        }

        // Delete todo
        function deleteTodo(id) {
            todos = todos.filter(todo => todo.id !== id);
            saveTodos();
            renderTodos();
        }

        // Set filter
        function setFilter(filter) {
            currentFilter = filter;

            // Update active button
            document.querySelectorAll('.filter-btn').forEach(btn => {
                btn.classList.remove('active');
            });
            event.target.classList.add('active');

            renderTodos();
        }

        // Get filtered todos
        function getFilteredTodos() {
            switch (currentFilter) {
                case 'active':
                    return todos.filter(todo => !todo.completed);
                case 'completed':
                    return todos.filter(todo => todo.completed);
                default:
                    return todos;
            }
        }

        // Render todos
        function renderTodos() {
            const list = document.getElementById('todoList');
            const filtered = getFilteredTodos();
            const stats = document.getElementById('stats');

            // Update stats
            const activeCount = todos.filter(todo => !todo.completed).length;
            stats.textContent = `${activeCount} item${activeCount !== 1 ? 's' : ''} left`;

            if (filtered.length === 0) {
                if (currentFilter === 'all' && todos.length === 0) {
                    list.innerHTML = '<li class="empty-state">No todos yet. Add one above!</li>';
                } else if (currentFilter === 'active') {
                    list.innerHTML = '<li class="empty-state">No active todos!</li>';
                } else {
                    list.innerHTML = '<li class="empty-state">No completed todos yet.</li>';
                }
                return;
            }

            list.innerHTML = filtered.map(todo => `
                <li class="todo-item ${todo.completed ? 'completed' : ''}">
                    <input 
                        type="checkbox" 
                        class="todo-checkbox" 
                        ${todo.completed ? 'checked' : ''} 
                        onchange="toggleTodo(${todo.id})"
                    >
                    <span class="todo-text">${escapeHtml(todo.text)}</span>
                    <button class="delete-btn" onclick="deleteTodo(${todo.id})" title="Delete todo">
                        &times;
                    </button>
                </li>
            `).join('');
        }

        // Escape HTML to prevent XSS
        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }
    </script>
</body>
</html>"}

